const ctx = $('Call Context Gather').first().json;
const ct = ctx.current_task || {};
const chain = ctx.ancestor_chain || [];
const leaves = ctx.linked_doc_leaves || [];

// ---- Agent rules (global + per-person) from the AI doc (Docs v3) ----
let pages = [];
try { pages = $('Load Agent Rules').first().json.body || []; } catch (e) {}
const allPages = [];
(function flat(arr){ for (const p of (arr||[])) { allPages.push(p); if (p.pages) flat(p.pages); } })(pages);
const globalPage = allPages.find(p => p.id === 'q7wz-44812');
const global_rules = (globalPage && globalPage.content) ? globalPage.content : '';
const global_rules_missing = !global_rules;

// ---- Trigger inputs: When Called (producer/webhook) else Form Trigger (manual) ----
const OPERATOR_ID = '2521617';
const OPERATOR_NAME = 'Franciszek Nowak';
let wc = {}; try { wc = $('When Called').first().json || {}; } catch (e) {}
let fm = {}; try { fm = $('Form Trigger').first().json || {}; } catch (e) {}
const reviewer_user_id = (wc.reviewer_user_id || fm.reviewer_user_id || OPERATOR_ID).toString().trim();
const caller_username = (wc.caller_username || OPERATOR_NAME);
const triggered_by = wc.triggered_by || 'explicit_command';
const invocation_type = wc.invocation_type || 'explicit';
const triggering_comment_text = (wc.triggering_comment_text || '').toString().trim();
const triggering_comment_id = (wc.triggering_comment_id || '').toString().trim();

const personalPage = allPages.find(p => p.name === ('Instrukcje dla agenta - ' + caller_username));
const person_rules = (personalPage && personalPage.content) ? personalPage.content : '';
const person_rules_missing = !person_rules;

// ---- Search results from Search (v1) ----
let task_comments = [], additional_context = '', sources_used = [], sources_filtered_out = 0;
try { const sr = $('Call Search').first().json; task_comments = sr.task_comments || []; additional_context = sr.additional_context || ''; sources_used = sr.sources_used || []; sources_filtered_out = sr.sources_filtered_out || 0; } catch(e) {}

// ---- Personal data from PD Verifier ----
let personal_data = false;
try { personal_data = $('Call PD Verifier').first().json.personal_data === true; } catch(e) {}

// ---- Assemble prompt ----
const lines = [];
if (global_rules) { lines.push('# Zasady ogólne agenta (obowiązują zawsze)'); lines.push(global_rules); lines.push(''); lines.push('---'); lines.push(''); }
if (person_rules) { lines.push('# Preferencje osoby zlecającej (' + caller_username + ')'); lines.push(person_rules); lines.push(''); lines.push('---'); lines.push(''); }

// Triggering message: what the user wrote to invoke this run
lines.push('# Wiadomość wywołująca tę akcję');
lines.push('Użytkownik ' + caller_username + ' napisał:');
lines.push('---');
lines.push(triggering_comment_text || '[treść wiadomości niedostępna]');
lines.push('---');
lines.push('');

if (task_comments.length) { lines.push('# Ostatnie komentarze w zadaniu'); for (const c of task_comments) { lines.push((c.author || 'nieznany') + ': ' + (c.text || '')); } lines.push(''); }
if (additional_context) { lines.push('# Dodatkowy kontekst (wyszukiwanie semantyczne)'); lines.push(additional_context); if (sources_used.length) lines.push('Źródła: ' + sources_used.join(', ')); lines.push(''); }

lines.push('# Zadanie');
lines.push(ct.name || '(bez nazwy)');
if (ct.description) { lines.push(''); lines.push(ct.description); }
if (chain.length) {
  lines.push(''); lines.push('# Kontekst nadrzędny (od najogólniejszego do najbliższego)');
  for (const a of chain.slice().reverse()) { lines.push(''); lines.push('## ' + (a.name || '')); if (a.description) lines.push(a.description); }
}
if (leaves.length) {
  lines.push(''); lines.push('# Szczegółowe wytyczne');
  for (const l of leaves) { lines.push('- ' + (l.name || '')); if (l.content) lines.push(l.content); }
}
lines.push('');
lines.push('Przygotuj wynik dla powyższego zadania. Możesz rozumować swobodnie, ale ostateczną odpowiedź zwróć w poniższej strukturze (pomin sekcję, jeśli pusta):');
lines.push('');
lines.push('## Wyniki');
lines.push('## Pytania do zlecającego');
lines.push('## Decyzje i kompromisy');
lines.push('');
lines.push('---');
lines.push('## Sugestie do procesu');

const prompt = lines.join('\n');

return [{ json: {
  prompt,
  impact: ctx.impact || '',
  personal_data,
  task_type: '',
  clickup_task_id: (ct.id || ''),
  triggered_by,
  invocation_type,
  reviewer_user_id,
  caller_user_id: reviewer_user_id,
  caller_username,
  process_type: ctx.process_type || '',
  assignee_user_id: ctx.assignee_user_id || '',
  creator_user_id: ctx.creator_user_id || '',
  global_rules_missing,
  person_rules_missing,
  triggering_comment_id
} }];

const md = ($('Call Invoke Model').first().json.completion || '').toString();
const bp = $('Build Prompt').first().json;
const reviewer = Number(bp.reviewer_user_id);
const model = $('Call Invoke Model').first().json.model || '';
const cost = $('Call Invoke Model').first().json.cost_pln;

const ops = [];
if (reviewer) ops.push({ type: 'tag', user: { id: reviewer } });
ops.push({ text: '\n' });

const LINK = /\[([^\]]+)\]\(([^)]+)\)/;
const BOLD = /\*\*([^*]+)\*\*/;
const CODE = /`([^`]+)`/;
const ITAL = /\*([^*]+)\*|_([^_]+)_/;

function inlineOps(t) {
  const out = [];
  let rest = String(t);
  while (rest.length) {
    let best = null, kind = null;
    const cands = [[LINK,'link'],[BOLD,'bold'],[CODE,'code'],[ITAL,'ital']];
    for (const c of cands) { const m = c[0].exec(rest); if (m && (best === null || m.index < best.index)) { best = m; kind = c[1]; } }
    if (!best) { out.push({ text: rest }); break; }
    if (best.index > 0) out.push({ text: rest.slice(0, best.index) });
    if (kind === 'link') out.push({ text: best[1], attributes: { link: best[2] } });
    else if (kind === 'bold') out.push({ text: best[1], attributes: { bold: true } });
    else if (kind === 'code') out.push({ text: best[1], attributes: { code: true } });
    else out.push({ text: best[1] || best[2], attributes: { italic: true } });
    rest = rest.slice(best.index + best[0].length);
  }
  return out.length ? out : [{ text: '' }];
}
function emit(inline, attrs) { for (const o of inline) ops.push(o); ops.push(attrs ? { text: '\n', attributes: attrs } : { text: '\n' }); }
function isRow(s){ const t=s.trim(); return t.length>1 && t.charAt(0)==='|' && t.charAt(t.length-1)==='|'; }
function isSep(s){ const t=s.trim(); return /^[|\s:-]+$/.test(t) && t.indexOf('-')>=0; }
function cellsOf(s){ return s.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(function(c){return c.trim();}); }

const L = md.replace(/\r/g,'').split('\n');
let i=0, gRow=0, inCode=false;
while (i < L.length) {
  const s = L[i];
  if (s.trim().indexOf('```') === 0) { inCode = !inCode; i++; continue; }
  if (inCode) { ops.push({ text: s }); ops.push({ text: '\n', attributes: { 'code-block': 'plain' } }); i++; continue; }
  if (isRow(s) && i+1 < L.length && isSep(L[i+1])) {
    const rows=[]; let j=i;
    while (j < L.length && isRow(L[j])) { rows.push(L[j]); j++; }
    for (let r=0; r<rows.length; r++) {
      if (r===1) continue;
      gRow++;
      const cs = cellsOf(rows[r]);
      for (const c of cs) { const io = inlineOps(c); for (const o of io) ops.push(o); ops.push({ text: '\n', attributes: { table: 'row-'+gRow } }); }
    }
    i=j; continue;
  }
  const t = s.replace(/^\s+/,'');
  let m;
  if (t.charAt(0)==='#') { const h=t.match(/^(#{1,6})\s+(.*)$/); if (h) { emit(inlineOps(h[2]), { header: Math.min(h[1].length,3) }); i++; continue; } }
  if ((m = t.match(/^[-*+]\s+(.*)$/))) { emit(inlineOps(m[1]), { list: 'bullet' }); i++; continue; }
  if ((m = t.match(/^\d+\.\s+(.*)$/))) { emit(inlineOps(m[1]), { list: 'ordered' }); i++; continue; }
  if (t.charAt(0)==='>') { emit(inlineOps(t.replace(/^>\s?/,'')), { blockquote: true }); i++; continue; }
  if (/^([-*_])\1{2,}$/.test(s.trim())) { i++; continue; }
  if (s.trim()==='') { i++; continue; }
  emit(inlineOps(s), null);
  i++;
}

ops.push({ text: '\n—\n' });
ops.push({ text: 'Przygotowane przez agenta AI (model: '+model+', koszt: '+cost+' PLN). Do weryfikacji — nie finalizuje zadania.', attributes: { italic: true } });
ops.push({ text: '\n' });
return [{ json: { ops } }];

parameters.query:
select coalesce(sum(cost_pln), 0) as total
from agent_runs
where clickup_task_id = $1;
